            MessageOutput.println("<location unavailable>");
            return;
        }
        if (frame == null) {
            MessageOutput.println("No frames on the current call stack");
        } else {
            printLocationWithSourceLine(threadInfo.getThread().name(), frame.location());
        }
        MessageOutput.println();
    }

