            "coordinates" : [
              0.5,
              3.0
            ]
          }
        }
      },
      {
        "_index" : "testindex",
        "_id" : "2",
        "_score" : 0.0,
        "_source" : {
          "geometry" : {
            "type" : "polygon",
            "coordinates" : [
              [
                [
                  2.5,
                  6.0
                ],
                [
                  0.5,
                  4.5
                ],
                [
                  1.5,
                  2.0
                ],
                [
                  3.5,
                  3.5
                ],
                [
                  2.5,
                  6.0
                ]
              ]
            ]
          }
        }
      }
    ]
  }
}
```

## Querying xy points

You can also use an xy query to search for documents that contain xy points. 

Create a mapping with `point` as `xy_point`:

```json
PUT testindex1
{
  "mappings": {
    "properties": {
      "point": {
        "type": "xy_point"
      }
    }
  }
}
```
{% include copy-curl.html %}

Index three points:

```json
PUT testindex1/_doc/1
{
  "point": "1.0, 1.0" 
}
```
{% include copy-curl.html %}

```json
PUT testindex1/_doc/2
{
  "point": "2.0, 0.0" 
}
```
{% include copy-curl.html %}

```json
PUT testindex1/_doc/3
{
  "point": "-2.0, 2.0" 
}
```
{% include copy-curl.html %}

Search for points that lie within the circle with the center at (0, 0) and a radius of 2:

```json
GET testindex1/_search
{
  "query": {
    "xy_shape": {
      "point": {
        "shape": {
          "type": "circle",
          "coordinates": [0.0, 0.0],
          "radius": 2
        }
      }
    }
  }
}
```
{% include copy-curl.html %}

xy point only supports the default `INTERSECTS` spatial relation, so you don't need to provide the `relation` parameter.
{: .note}

The following image depicts the example. Points 1 and 2 are within the circle, and point 3 is outside the circle.

![xy point query]({{site.url}}{{site.baseurl}}/images/xy_query_point.png){: width="300" }

The response returns documents 1 and 2:

```json
{
  "took" : 575,
  "timed_out" : false,
  "_shards" : {
    "total" : 1,
    "successful" : 1,
    "skipped" : 0,
    "failed" : 0
  },
  "hits" : {
    "total" : {
      "value" : 2,
      "relation" : "eq"
    },
    "max_score" : 0.0,
    "hits" : [
      {
        "_index" : "testindex1",
        "_id" : "1",
        "_score" : 0.0,
        "_source" : {
          "point" : "1.0, 1.0"
        }
      },
      {
        "_index" : "testindex1",
        "_id" : "2",
        "_score" : 0.0,
        "_source" : {
          "point" : "2.0, 0.0"
        }
      }
    ]
  }
}
```

